                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE or replace table snitch_db.maplemonk.offline_walkins as WITH Orders AS ( SELECT CAST(order_date AS DATE) AS order_dt, marketplace_mapped, BRANCH_CODE, COUNT(DISTINCT order_name) AS Orders, SUM(SUBORDER_QUANTITY) AS QTY FROM snitch_db.maplemonk.store_fact_items_offline WHERE DOC_PREFIX !=\'OMS\' AND order_date >= \'2025-07-01\' AND marketplace_mapped NOT LIKE \'%- WH -%\' AND ORDER_STATUS = \'Processed\' AND category != \'CARRY BAG\' GROUP BY order_dt, marketplace_mapped, BRANCH_CODE ), Stores AS ( SELECT STORE_CODE, CASE WHEN STORE_CODE = \'Snitch-Kothapet-Hyderabad\' THEN 47 WHEN STORE_CODE = \'Snitch-Orion-Avenue-Mall-Bangalore\' THEN 56 WHEN STORE_CODE = \'Snitch-Kukatpally-Hyderabad\' THEN 20 WHEN STORE_CODE = \'Snitch-Sarath-City-Capital-Mall-Hyderabad\' THEN 16 WHEN STORE_CODE = \'Snitch-M5e-City-Mall-Bangalore\' THEN 62 WHEN STORE_CODE = \'Snitch-Lulu-Mall-Bangalore\' THEN 43 WHEN STORE_CODE = \'Snitch-Orion-Mall-Bangalore\' THEN 81 WHEN STORE_CODE = \'Snitch-Bhartiya-City-Mall-Bangalore\' THEN 41 WHEN STORE_CODE = \'Snitch-PMC-Bangalore\' THEN 55 WHEN STORE_CODE = \'Snitch-Waltair-Vizag\' THEN 29 WHEN STORE_CODE = \'Snitch-Mantri-Avenue-Koramangala-Bangalore\' THEN 19 WHEN STORE_CODE = \'Snitch-Jayanagar-Bangalore\' THEN 3 WHEN STORE_CODE = \'Snitch-New-Bel-Road-Bangalore\' THEN 14 WHEN STORE_CODE = \'Snitch-Banashankari-Bangalore\' THEN 57 WHEN STORE_CODE = \'Snitch-HSR-Layout-Bangalore\' THEN 13 WHEN STORE_CODE = \'Snitch-Elan-Miracle-Gurgaon\' THEN 67 WHEN STORE_CODE = \'Snitch-Palladium-Mall-Chennai\' THEN 84 WHEN STORE_CODE = \'Snitch-Gandhipuram-Rajahmundry\' THEN 50 WHEN STORE_CODE = \'Snitch-Gokul-Road-Hubli\' THEN 51 WHEN STORE_CODE = \'Snitch-City-Center-Mall-Mangalore\' THEN 27 WHEN STORE_CODE = \'Snitch-Vyapar-Vihar-Bilaspur\' THEN 87 WHEN STORE_CODE = \'Snitch-C-Road-Sardarpura-Jodhpur\' THEN 40 WHEN STORE_CODE = \'Snitch-Malviya-Nagar-Jaipur\' THEN 91 WHEN STORE_CODE = \'Snitch-Gumanpura-Kota\' THEN 86 WHEN STORE_CODE = \'Snitch-Mathura-road-Faridabad\' THEN 82 WHEN STORE_CODE = \'Snitch-Mittal-Mall-Ajmer\' THEN 64 WHEN STORE_CODE = \'SNITCH-COCO-LAJPAT-NAGAR\' THEN 49 WHEN STORE_CODE = \'SNITCH-COCO-MYSORE\' THEN 98 WHEN STORE_CODE = \'SNITCH-FOCO-VAISHALINAGAR\' THEN 39 WHEN STORE_CODE = \'SNITCH-COCO-SECTOR-29\' THEN 73 WHEN STORE_CODE = \'SNITCH-COFO-KARIMNAGAR\' THEN 79 WHEN STORE_CODE = \'SNITCH-COCO-GUWAHATI\' THEN 58 WHEN STORE_CODE = \'SNITCH-COCO-JANAKPURI\' THEN 90 WHEN STORE_CODE = \'SNITCH-COCO-JANAKPURI\' THEN 90 WHEN STORE_CODE = \'SNITCH-COCO-SECTOR-50\' THEN 85 WHEN STORE_CODE = \'SNITCH-COCO-RAIPUR\' THEN 61 WHEN STORE_CODE = \'Snitch-Toli-Chowki-Hyderabad\' THEN 77 WHEN STORE_CODE = \'SNITCH-COFO-PALLADIUM-CHENNAI\' THEN 84 WHEN STORE_CODE = \'SNITCH-COCO-BANASHANKARI\' THEN 57 WHEN STORE_CODE = \'SNITCH-COCO-BHARTIYA-CITY\' THEN 41 WHEN STORE_CODE = \'SNITCH-COCO-PMC-WHITEFIELD-MALL\' THEN 55 WHEN STORE_CODE = \'SNITCH-COCO-M5-MALL\' THEN 62 WHEN STORE_CODE = \'SNITCH-FOCO-AJMER-MITTAL\' THEN 64 WHEN STORE_CODE = \'SNITCH-COFO-VIZAG\' THEN 29 WHEN STORE_CODE = \'SNITCH-COCO-FARIDABAD\' THEN 82 WHEN STORE_CODE = \'SNITCH-COCO-ELAN-MIRACLE\' THEN 67 WHEN STORE_CODE = \'SNITCH-COCO-ORION-MALL\' THEN 56 WHEN STORE_CODE = \'SNITCH-COFO-NIZAMABAD\' THEN 100 WHEN STORE_CODE = \'SNITCH-FOCO-C-ROAD-JODHPUR\' THEN 40 WHEN STORE_CODE = \'SNITCH-COCO-KORMANGLA\' THEN 19 WHEN STORE_CODE = \'SNITCH-COFO-HUBLI\' THEN 51 WHEN STORE_CODE = \'SNITCH-COCO-ORION-MALL-AVENUE\' THEN 56 WHEN STORE_CODE = \'SNITCH-COCO-LULU-MALL\' THEN 43 WHEN STORE_CODE = \'SNITCH-COCO-BEL-ROAD\' THEN 14 WHEN STORE_CODE = \'SNITCH-COCO-JAYANAGAR\' THEN 3 WHEN STORE_CODE = \'SNITCH-COCO-HSR-LAYOUT\' THEN 13 WHEN STORE_CODE = \'SNITCH-COFO-KOTHAPET\' THEN 47 WHEN STORE_CODE = \'SNITCH-FOCO-MALVIYA-NAGAR\' THEN 91 WHEN STORE_CODE = \'SNITCH-FOCO-KOTA\' THEN 86 WHEN STORE_CODE = \'SNITCH-COFO-KUKATPALLY\' THEN 20 WHEN STORE_CODE = \'SNITCH-COFO-CC-MANGALORE\' THEN 27 WHEN STORE_CODE = \'SNITCH-COFO-BILASPUR\' THEN 87 WHEN STORE_CODE = \'SNITCH-COFO-SARATH-CITY\' THEN 16 WHEN STORE_CODE = \'SNITCH-COFO-RAJAHMUNDRY\' THEN 50 WHEN STORE_CODE = \'SNITCH-FOCO-NIKOL\' THEN 99 ELSE NULL END AS Code, GREATEST(\"IN\", OUT) AS Walk_ins, CAST(TO_TIMESTAMP(DATETIME, \'MM/DD/YYYY HH24:MI:SS\') AS DATE) AS date_cast FROM snitch_db.maplemonk.snitch_db_get_store_count ), metricss as ( Select * from snitch_db.maplemonk.Offline_Detailed_Summary_V2 ) SELECT s.STORE_CODE, s.Code, s.date_cast AS store_date, CURRENT_DATE AS Current_date_mapped, s.Walk_ins, o.order_dt AS order_date, o.marketplace_mapped, o.Orders, o.QTY, B.TODAY_SALES, B.TARGET, B.MTD_SALES, B.MTD, B.BILLS, B.MULTIES, B.QTY AS QTYSS, B.ATV, B.UPT, B.ASP, B.AM, B.STATE FROM Stores s LEFT JOIN Orders o ON s.Code = o.BRANCH_CODE AND s.date_cast = o.order_dt LEFT JOIN METRICSS B ON s.Code = B.BRANCH_CODE AND s.date_cast = B.DATE ;",
